#include <bits/stdc++.h>
using namespace std;

int main() {
    int s, t, x;
    cin >> s >> t >> x;
    if (s < t) {
        cout << (s <= x and x < t ? "Yes" : "No") << '\n';
    } else {
        cout << (x < t or s <= x ? "Yes" : "No") << '\n';
    }
}

s, t, x = map(int, input().split())
if s < t:
    print("Yes" if s <= x < t else "No")
else:
    print("Yes" if x < t or s <= x else "No")
